import { defineComponent, h, type PropType } from 'vue';
import { getSpinnerSize, spinnerStyleKeys } from '../lib/core';
import type { SpinnerSize } from '../lib/core';
import styles from './spinner.module.scss';

export const Spinner = defineComponent({
	name: 'Spinner',
	props: {
		size: {
			type: String as PropType<SpinnerSize>,
			default: 'default',
		},
	},
	setup(props, { attrs }) {
		return () =>
			h(
				'svg',
				{
					...attrs,
					'data-slot': 'spinner',
					role: 'status',
					'aria-label': 'Loading',
					'data-size': getSpinnerSize(props.size),
					xmlns: 'http://www.w3.org/2000/svg',
					viewBox: '0 0 24 24',
					fill: 'none',
					stroke: 'currentColor',
					'stroke-width': 2,
					'stroke-linecap': 'round',
					'stroke-linejoin': 'round',
					class: [styles[spinnerStyleKeys.root], attrs.class],
				},
				[h('path', { d: 'M21 12a9 9 0 1 1-6.219-8.56' })],
			);
	},
});

export default Spinner;

@use '../../../styles/variables/colors' as *;

// 旋转动画
@keyframes tile-spinner-rotate {
	from {
		transform: rotate(0deg);
	}

	to {
		transform: rotate(360deg);
	}
}

// Spinner 根元素（svg）
.root {
	flex-shrink: 0;
	color: var(--tile-spinner-color, $muted-foreground);
	animation: tile-spinner-rotate 0.8s linear infinite;

	// 尺寸
	&[data-size='sm'] {
		width: $spacing-4;
		height: $spacing-4;
	}

	&[data-size='default'] {
		width: var(--tile-spinner-size, $spacing-5);
		height: var(--tile-spinner-size, $spacing-5);
	}

	&[data-size='lg'] {
		width: $spacing-8;
		height: $spacing-8;
	}
}
